insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('dd1ee821-ae46-4cf8-9852-81d932eed1ed','ja','taiwan-castella-expectation-vs-reality','台湾カステラ(期待と実際)','期待していた華やかなデザートと実際の地味な仕上がりとのギャップを指すミーム','ドラマ「梨泰院クラス」(2020年)で、登場人物がSNSで話題になった台湾風カステラを期待して作ったのに、平凡なカステラができあがる場面から派生したミーム。「期待していたものと実際が違う」という状況に「台湾カステラが食べたかったのに」というフレーズで反応する用途で使われる。その後TikTokでもこのフレーズを使ったパロディコント動画が継続的に作られている。','2020年に放送されたドラマ「梨泰院クラス」のチョ・イソというキャラクターのエピソードに由来し、その後TikTokなどで繰り返しパロディされるリアクションミームとして定着した。','期待していた結果と実際の結果が違うときに自嘲的に引用する',null,array['台湾カステラ食べたかったのに','チョ・イソ台湾カステラ','대만 카스테라 (기대와 실제)'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('d3b3be4b-0785-40be-9f15-5ddfa2e27921','ja','jannabi-for-hesitant-lovers-cover-challenge','ジャンナビ(JANNABI)「躊躇う恋人たちのために」カバーチャレンジ','2019年発売のジャンナビのバラードが世代を超えてカバーされるTikTokの流行','ジャンナビの2019年正規3集収録曲「躊躇う恋人たちのために」は、発売翌年からバスキングやカバー動画がSNSで拡散し、「国民的初恋ソング」として定着した。特に女性キー(女性音域)にアレンジしたカバーがTikTokで根強い人気を集め、告白・恋の予感・初恋の雰囲気を演出する動画のBGMとしてよく使われる。','2019年にジャンナビの正規3集「伝説」に収録され発売され、翌年からバスキングやSNSカバー動画が拡散し、世代を超えたカバーソングとして定着した。','告白・恋の予感・初恋の雰囲気を演出する動画のBGMやカバーソングコンテンツに使われる',null,array['躊躇う恋人たちのためにカバー','ジャンナビ初恋ソング','잔나비 주저하는 연인들을 위해 커버 챌린지'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('ed082c66-a568-4147-9a2c-5c8898334dd9','ja','im-the-ceo-im-the-employee','私は代表、私は社員','代表と社員の立場の違いをコミカルに対比させるリールズフォーマット','一人二役で代表と社員を演じ分け、社員は「社員だから退社もできるし休暇にも行ける」と堂々と話す一方、代表は発言する機会すら得られずシーンが切られるという構成。会社員のささやかな自由と代表の苦労を対比させるミームで、企業の広報コンテンツにも応用される。','2025年頃Instagramリールズで流行したフォーマットで、社員の自由と代表の負担を対比させる構成が繰り返し使われ、一つのテンプレートとして定着した。','会社員のささやかな特権(退社、休暇など)を誇らしげに語るとき',null,array['代表vs社員ミーム','난 대표 난 직원'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('1aa02b46-ae84-479d-9ecc-da1cfd50fa9a','ja','bombardiro-crocodilo','ボンバルディーロ・クロコディーロ(Bombardiro Crocodilo)','AIで作られた爆撃機+ワニ合成キャラクター、イタリアン・ブレインロットの代表格','爆撃機の胴体にワニの顔がついたAI生成キャラクターで、イタリア語のナレーションとともに奇怪な世界観を持つ「ブレインロット」キャラクターシリーズの一つ。トラララレロ・トラララなど他のブレインロットキャラクターたちと絡み合う世界観動画へと拡張された。韓国の10代・20代の間でも「意味は分からないけど笑える」ミームとして共有されている。','2025年初頭、AI画像・音声生成ツールで作られたイタリア語ブレインロットキャラクターシリーズの一つとしてTikTokで拡散した。','意味不明だけど笑えるAIミームを共有するときに使う',null,array['Bombardino Crocodilo','봄바르디로 크로코딜로(Bombardiro Crocodilo)'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('5787e66d-04d3-48e2-bebf-65ea5bbb48b9','ja','bts-butter-challenge','BTS「Butter」チャレンジ','2021年のBTS「Butter」発売とともに広まったTikTokのポイント振り付けチャレンジ','BTSが2021年5月に発表した英語シングル「Butter」のサビのポイント振り付けを真似するTikTokチャレンジ。指でバターを塗るように滑らかに動かす動作が特徴で、ファンから一般ユーザーまで参加し世界的に拡散した。簡単な動作が中心のため、カバーダンス初心者にも多く真似された。','2021年5月21日「Butter」音源公開直後からTikTokで振り付けチュートリアルやカバー動画が急速に広まり、チャレンジとして定着した。','軽快なK-POPダンスチャレンジの例として言及するときに使う',null,array['Butterチャレンジ','バターダンスチャレンジ','BTS 버터(Butter) 챌린지'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('1c2f96af-2da2-4ffe-aa79-c405ed2bf0ac','ja','woodz-drowning-cover-challenge','WOODZ「Drowning」カバーチャレンジ','2022年発売曲が放送・SNSカバーで遅れて逆走したバラードミーム','WOODZ(チョ・スンヨン)が2022年に発表したバラード「Drowning」は発売当初大きな注目を浴びなかったが、その後放送のステージなどを経て再び脚光を浴び始めた。2024〜2025年にはキム・ジョングクなど著名人がSNSカバー動画を投稿して話題になり、2025年には各種授賞式のステージにも上がり、代表的な逆走ミームソングに挙げられる。','WOODZが2022年に発表した「Drowning」は当初注目されなかったが、放送のステージやSNSカバー動画を通じて遅れて逆走し、2025年には音源チャートの上位圏や年末授賞式のステージにまで上がった代表的な逆走事例となった。','バラードのカバー動画や「逆走ソング」紹介コンテンツに使われる',null,array['Drowningチャレンジ','ドラウニングカバー','WOODZドラウニング','우즈(WOODZ) Drowning 커버 챌린지'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('42f3a6ef-2340-45d0-b24c-6243b2f2c12b','ja','midari','ミダリ','シットコム「スンプン産婦人科」のおてんば娘キャラクター','1998年のSBSシットコム「スンプン産婦人科」で子役キム・ソンウンが演じた娘「ミダリ」は、生意気で突拍子もないキャラクターとして国民的な人気を集めた。理不尽さを訴えて号泣するシーンが、後にインターネットでリアクション画像として爆発的に再消費された。','SBSシットコム「スンプン産婦人科」(1998〜2000年)、キム・ソンウン出演','理不尽さや大げさな感情を表現するときにリアクション画像として使う',null,array['パク・ミダリ','スンプン産婦人科ミダリ','미달이'],'[{"text": "私完全にミダリみたいに悔しいｗｗ", "situation": "カカオトーク"}, {"text": "このリアクション画像ミダリ級の号泣だ", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('6d6824f0-8c46-41ec-af5f-88ea2898714f','ja','challenge-golden-bell','挑戦!ゴールデンベル','高校生たちの最終問題への挑戦を描いたKBSの長寿クイズコーナー','1999年1月「接続!新世代」のコーナーとして始まった「挑戦!ゴールデンベル」は、高校生たちが問題を解きながら脱落していき、最後に残った1人がゴールデンベル問題に挑戦する形式で、その後独立番組となり長寿コンテンツとして定着した。「最終問題」という表現自体が決定的瞬間を意味するミームとして使われる。','KBS「接続!新世代」のコーナーとして始まり、その後「挑戦!ゴールデンベル」として独立(1999年)','決定的な最後の瞬間や最終関門を表現するときに引用する',null,array['最終問題','ゴールデンベルを鳴らせ','도전 골든벨'],'[{"text": "もう最終問題だよ、ゴールデンベルの予感", "situation": "カカオトーク"}, {"text": "この瞬間まさに挑戦ゴールデンベル級の緊張感", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('7dfb16fb-3c28-4ade-bdba-9547d0baa948','ja','babyvox-get-up','ベイビーボックス「Get Up」','韓国初のセクシーコンセプトとして話題を集めたベイビーボックスの2001年タイトル曲','ベイビーボックスが2001年6月に発売したアルバムのタイトル曲で、当時複数のメディアから「韓国ガールズグループ初のセクシーコンセプト」と評価された。その後ベイビーボックスは中国・東南アジア市場でも大きな人気を得て、活動の幅を広げた。','2001年6月4日ベイビーボックスのアルバムタイトル曲としてアジア4カ国同時発売','第1世代ガールズグループのコンセプトの変遷を語るときに言及する',null,array['ベボGet Up','베이비복스 - Get Up'],'[{"text": "韓国ガールズグループのセクシーコンセプトの元祖がベイビーボックスだったね", "situation": "カカオトーク"}, {"text": "このコンセプトの変遷が興味深い", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('20c4d1a6-a051-4952-b7e1-5a33728de42d','ja','armageddon-challenge','「Armageddon」チャレンジ','aespaのコンサートで火がついた「Armageddon」ファンダンスチャレンジ','2024年6月30日aespaの単独コンサート「SYNK: PARALLEL LINE」で予告なく始まったダンスチャレンジコーナーに歌手のチョンハとヘリが参加し話題になった。「Armageddon」はその年「Supernova」「Whiplash」とともにaespaの3連続ヒット曲に数えられる。','2024年6月30日aespaコンサート現場のファンチャレンジ','コンサートのファンチャレンジ文化について語るときに言及する',null,array['アルマゲドンチャレンジ','aespaコンサートチャレンジ','Armageddon 챌린지'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('063ce340-c496-48be-a88c-5cc5d5e370bd','ja','you-too-me-too-yanadoo','あなたも私もヤナドゥ','英語教育の広告コピーがチムチャンメンのモノマネで再び話題になった事例','オンライン英語教育ブランド「ヤナドゥ」の広告コピー「君も?僕も?ヤナドゥ」はもともと2010年代半ばに作られた広告文句だったが、ストリーマーのチムチャンメンが配信でこれを頻繁にモノマネしたことで、2019年末にTwitchやオンラインコミュニティで再び流行語のように使われた。頭文字だけを取った「ㄴㄷ?」「ㅇㄴㄷ」のような略語で書かれることもあった。','ヤナドゥの広告コピー、チムチャンメンのモノマネで再流行(2019年)','何かを一緒にしようと誘うときに冗談めかして使う',null,array['ヤナドゥ','チムチャンメンヤナドゥ','너두 나두 야나두'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('d574e4cd-eaeb-453a-9994-020e2b0a6f7d','ja','galgari-three-brothers','カルガリ三兄弟','1999〜2003年「ギャグコンサート」の人気コーナーと流行語「大根をください」','パク・ジュニョン、チョン・ジョンチョル、イ・スンファンが出演したギャグコンサートのコーナー「カルガリ三兄弟」は、「大根をください!」という流行語とともに大人気を博し、ギャグコンサートの黄金期を牽引した。2003年7月に終了するまで「カルガリファミリー」という名でスターダムにのし上がったコメディアンたちを輩出した。','KBSギャグコンサートのこのコーナーは、もともと海外ドラマ「緊急救助911」を韓国語吹き替えでパロディした「パロディボイス」という名前で始まった。2001年9月の初放送で、水に落ちた人を助けるために船を作ろうと大根の中身を歯でくり抜くシーンが予想外に大きな笑いを呼んだことから、これを最後に繰り返し見せる構成にコーナーを改編し、名前も「カルガリ三兄弟」に変わった。パク・ジュニョン、チョン・ジョンチョル、イ・スンファンが出演し「大根をください」という流行語を残し、2003年7月まで放送されギャグコンサート初期を代表するコーナーとして定着した。','何かを気の利いた形でお願いするときに「大根をください」のようにパロディできる',null,array['大根をください','カルガリファミリー','갈갈이 삼형제'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('dfef04c8-3e40-4d14-a57e-5920278584ed','ja','traffic-light-color-meme','信号ミーム','イ・ムジンの2021年ヒット曲「信号」のサビの色にまつわる歌詞が、さまざまな状況になぞらえてパロディされるミーム','イ・ムジンが2021年5月14日に発売した初のシングル「信号」は、大人になった青春の心情を信号機になぞらえた曲で、その年の下半期に爆発的な人気を得た。サビの「赤色、青色、その間の3秒」という歌詞が、対照的な2つの色で表現できるあらゆる状況(株価チャートなど)にパロディとして活用されるミームになった。','イ・ムジン初のシングル「信号」(2021年5月14日発売)の歌詞','赤と青のように対照的な2つの状況を表現するときに使いやすい',null,array['イ・ムジン信号ミーム','신호등 색깔 밈'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('8c30c56f-ee28-4706-b85d-8570bc2e5183','ja','tes-hyeong','テス兄さん','ナ・フナが2020年の秋夕特別公演で歌った曲の中でソクラテスを呼ぶ愛称が万能流行語になった事例','歌王ナ・フナが2020年8月に発売した正規9集のタイトル曲「テス兄さん!」は、父への恋しさをソクラテスに語りかけるように歌った曲だ。2020年の秋夕特別公演「大韓民国アゲイン・ナフナ」で熱唱し爆発的な人気を得て、「世の中はなぜこうなんだ」と問いかけるサビが、あらゆる状況になぞらえてパロディされる万能流行語として定着した。','ナ・フナ正規9集「9つの物語」タイトル曲「テス兄さん!」(2020年8月20日発売)、2020年秋夕特別公演「大韓民国アゲイン・ナフナ」','「テス兄さん」の部分を他の対象に置き換えて世の中への不満をぼやくときに使いやすい',null,array['テス兄さん!','ああ、テス兄さん','테스형'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('9c2d7b1b-23fe-4870-9b6d-83fc78d7d32e','ja','reporter-lee-hanseok-model-tower-training','イ・ハンソク記者 模型塔訓練','SBSのイ・ハンソク記者が特殊部隊兵営体験中、11m模型塔で上げた奇怪な悲鳴が鉄板ネタとして定着','2011年8月、SBSのイ・ハンソク記者が陸軍特殊戦司令部の特戦キャンプ(兵営体験)リポートを撮影中、11mの模型塔訓練に挑戦した際に上げた独特の痰が絡んだような悲鳴が話題になった。この映像は2011年8月8日からDCインサイドの合成鉄板ネタギャラリーで様々なパロディ素材として使われ、鉄板ネタとして定着した。その後パク・デギ、クァク・スンギュなど他の記者の映像とも組み合わされ、いわゆる「記者ネタ」ブームを牽引した。','2011年8月SBSニュースの特戦キャンプ体験リポート映像、DCインサイド合成鉄板ネタギャラリーで流行が始まった','突拍子もなく笑える反応を表現するときに無難に使える',null,array['イ・ハンソク記者特戦司令部体験','SBSイ・ハンソク記者','特戦キャンプ悲鳴','이한석 기자 모형탑 훈련'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('6a94ca15-7faa-419a-b743-2516e9ce7068','ja','ktf-na-i-dont-know-either','KTF Na「お父さん、僕は誰ですか」「私もよく分からん」','無料通話を象徴するために即興で作られたKTF Na広告の親子再会のセリフ','2000年5月、KTFはブランド「Na」を発表し、「お父さん、僕は誰ですか」と尋ねる息子と「私もよく分からん」と答える父親の対話を収めた広告を発表した。無料を意味する「0」を強調するため、父親が即興で頭を丸く描く動作を入れたと伝えられている。俳優パク・ヨンジンとキム・サンギョンが出演し、当時最高のヒット広告に数えられた。','2000年5月KTF Na TV広告、パク・ヨンジン・キム・サンギョン出演','よく分からないと言葉を濁すときに「私もよく分からん」を引用する',null,array['私もよく分からん','KTF Na 아버지 나는 누구예요 나도 잘 몰러'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('edd7bd1d-569d-4885-82c3-37110282fee6','ja','psy-champion','PSY「チャンピオン」','2002年ワールドカップの赤い悪魔の応援に触発されたPSYの健全な応援歌','PSYが2002年韓日ワールドカップ当時ソウル広場で繰り広げられた赤い悪魔の応援を見て触発されて作った曲で、ハロルド・ファルターマイヤーの「Axel F」をサンプリングしている。2002年9月に発売され大ヒットし、PSYに「健全に遊ぶ歌手」という新たなイメージをもたらした。','2002年ワールドカップ赤い悪魔の応援現場から着想を得て作曲、2002年9月19日発売','応援歌やパーティーの雰囲気を盛り上げるときに今も頻繁に使われる',null,array['Champion','2002年ワールドカップチャンピオン','싸이 - 챔피언'],'[{"text": "今日の会食の雰囲気を盛り上げるためにチャンピオンをかけよう", "situation": "会食のグループチャット"}, {"text": "この応援まさにチャンピオン級のテンションだ", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('c91ddd65-5ef0-473d-b01c-7d1c3512c4c9','ja','gangnam-style','江南スタイル','PSYの馬踊りとともに世界的に広まった2012年最大のヒットチャレンジ','2012年7月に発売されたPSYの「江南スタイル」は、振付師イ・ジュソンが作った「馬踊り」とともにYouTubeを通じて世界的に拡散した。「エレンの部屋」出演などでアメリカのテレビにも進出し、韓国大衆歌謡として初めて30カ国以上でチャート1位を記録した。','2012年7月PSY正規6集タイトル曲、振付師イ・ジュソンの馬踊り','楽しい雰囲気やチャレンジを引用するときに幅広く無難に使える',null,array['馬踊り','オッパ江南スタイル','강남스타일'],'[{"text": "今日の会食は江南スタイルの馬踊りで締めよう", "situation": "会食のグループチャット"}, {"text": "このチャレンジ江南スタイル級の波及力だ", "situation": "SNSコメント"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('70ee6329-57be-4547-bd14-a833bbc3dbfa','ja','any-song-challenge','「Any Song」チャレンジ','ZICOの「Any Song(アムノレ)」に合わせて腕を振る簡単な振り付けチャレンジ','2020年1月、ZICOが新曲「Any Song」の発売とともにファサと撮影したチャレンジ動画を投稿したことから始まった。肩を揺らし腕を振る簡単な動作で老若男女誰でも真似できたため、急速に広まった。数多くの芸能人やインフルエンサーが参加し、K-POPチャレンジ文化の元祖と評価されている。','ZICOが2020年1月13日「Any Song」発売直前にファサと共に撮影しSNSに投稿した動画から始まった','チャレンジ文化について語るときに簡単なチャレンジの代名詞として言及する',null,array['Any Song Challenge','ZICOアムノレチャレンジ','아무노래 챌린지'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values ('9f480f20-5b12-40b4-b3bb-513a4f0f8c39','ja','bartz-liberation-war','バーツ解放戦争','リネージュ2サーバーの独裁に立ち向かった2004年のユーザー連合戦争','2004年6月から2008年3月まで、オンラインゲーム「リネージュ2」の「バーツ」サーバーで、サーバーを掌握したDK血盟の独裁に対抗して一般ユーザーたちが連合して立ち向かった事件で、20万人以上が参加し「オンライン初の市民革命」と呼ばれ、ゲームファンタジー小説の定番設定にも大きな影響を残した。','2004年6月、リネージュ2バーツサーバーを掌握した「ドラゴンナイツ(DK)血盟」が低レベルユーザーの必需品の税率を上げるなど独占的な運営を強めたことに対し、多数のユーザー連合である「バーツ連合軍」が結成され対抗したことから始まった。戦争は2008年3月まで続き、延べ20万人が参加したと伝えられ、掲示板には戦況を伝える投稿が殺到し、一般メディアもこれを「オンライン市民革命」になぞらえて報道した。その後、論文・展示・文学など様々なコンテンツとして再生産され、国内オンラインゲーム史に残る屈指の事件として語り継がれている。','オンラインゲームコミュニティ文化の事例として言及する',null,array['바츠 해방전쟁'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null) on conflict (meme_id, locale) do nothing;
